25	#define DATA_SIZE_DEFAULT (1024u)
26	#define AES_KEY_SIZE          (16)
27	#define AES_IV_SIZE           (16)
28	#define SHA1_KEY_SIZE         (20)
29	#define SHA1_96_DIGEST_SIZE   (12)
30	#define SHA1_FULL_DIGEST_SIZE (20)
