34	    uint8_t aes_iv[AES_IV_SIZE];
35	    uint8_t hmac_key[SHA1_KEY_SIZE];
36	    size_t datasize;                       /* payload bytes, from the datasize knob */
37	    uint8_t *plaintext;                    /* datasize bytes, malloc'd in init */
38	    uint8_t *golden_ciphertext;            /* datasize bytes */
39	    uint8_t golden_mac[SHA1_96_DIGEST_SIZE];
40	};
41	
42	static void hmac_sha1_96(const uint8_t *key, const uint8_t *msg, size_t len, uint8_t *out) {
43	    HMAC_CTX *ctx = s_HMAC_CTX_new();
44	    s_HMAC_Init_ex(ctx, key, SHA1_KEY_SIZE, s_EVP_sha1(), NULL);
45	    s_HMAC_Update(ctx, msg, len);
46	    uint8_t full_mac[SHA1_FULL_DIGEST_SIZE];
47	    unsigned int outlen;
48	    s_HMAC_Final(ctx, full_mac, &outlen);
49	    s_HMAC_CTX_free(ctx);
50	    memcpy(out, full_mac, SHA1_96_DIGEST_SIZE);
51	}
52	
53	static void aes_encrypt(const uint8_t *key, const uint8_t *iv, const uint8_t *in, uint8_t *out, size_t len) {
54	    EVP_CIPHER_CTX *ctx = s_EVP_CIPHER_CTX_new();
55	    s_EVP_EncryptInit_ex(ctx, s_EVP_aes_128_cbc(), NULL, key, iv);
56	    s_EVP_CIPHER_CTX_set_padding(ctx, 0);
57	    int outlen;
58	    s_EVP_EncryptUpdate(ctx, out, &outlen, in, len);
59	    int outlen2;
60	    s_EVP_EncryptFinal_ex(ctx, out + outlen, &outlen2);
61	    s_EVP_CIPHER_CTX_free(ctx);
62	}
63	
64	static void aes_decrypt(const uint8_t *key, const uint8_t *iv, const uint8_t *in, uint8_t *out, size_t len) {
65	    EVP_CIPHER_CTX *ctx = s_EVP_CIPHER_CTX_new();
66	    s_EVP_DecryptInit_ex(ctx, s_EVP_aes_128_cbc(), NULL, key, iv);
67	    s_EVP_CIPHER_CTX_set_padding(ctx, 0);
68	    int outlen;
69	    s_EVP_DecryptUpdate(ctx, out, &outlen, in, len);
70	    int outlen2;
71	    s_EVP_DecryptFinal_ex(ctx, out + outlen, &outlen2);
72	    s_EVP_CIPHER_CTX_free(ctx);
73	}
74	
75	static void hmac_sha1_avx_compute_golden(struct hmac_sha1_avx_data *d) {
76	    aes_encrypt(d->aes_key, d->aes_iv, d->plaintext, d->golden_ciphertext, d->datasize);
77	    hmac_sha1_96(d->hmac_key, d->golden_ciphertext, d->datasize, d->golden_mac);
78	}
