81	    if (s_EVP_CIPHER_CTX_new && s_EVP_EncryptInit_ex && s_EVP_DecryptInit_ex && s_EVP_aes_128_cbc() && s_HMAC_CTX_new && s_EVP_sha1) {
82	        struct hmac_sha1_avx_data *d = (struct hmac_sha1_avx_data *)malloc(sizeof(*d));
83	        if (!d) return EXIT_SKIP;
84	        int64_t knob = get_testspecific_knob_value_int(test, "datasize", DATA_SIZE_DEFAULT);
