89	        d->plaintext = (uint8_t *)malloc(d->datasize);
90	        d->golden_ciphertext = (uint8_t *)malloc(d->datasize);
91	        if (!d->plaintext || !d->golden_ciphertext) {
92	            report_fail_msg("OOM allocating %zu bytes of plaintext/golden", 2 * d->datasize);
93	        }
94	
95	        memset_random(d->aes_key, AES_KEY_SIZE);
96	        memset_random(d->aes_iv, AES_IV_SIZE);
97	        memset_random(d->hmac_key, SHA1_KEY_SIZE);
98	        memset_random(d->plaintext, d->datasize);
99	
100	        hmac_sha1_avx_compute_golden(d);
101	
102	        test->data = d;
103	        return EXIT_SUCCESS;
104	    } else {
105	        log_skip(TestResourceIssueSkipCategory, "OpenSSL library is not available or the current version is not supported");
106	        return EXIT_SKIP;
107	    }
108	}
