111	    struct hmac_sha1_avx_data *d = (struct hmac_sha1_avx_data *)test->data;
112	
113	    uint8_t *ciphertext = (uint8_t *)malloc(d->datasize);
114	    uint8_t *decrypted = (uint8_t *)malloc(d->datasize);
115	    uint8_t *mac = (uint8_t *)malloc(SHA1_96_DIGEST_SIZE);
116	
117	    TEST_LOOP(test, 256) {
118	        aes_encrypt(d->aes_key, d->aes_iv, d->plaintext, ciphertext, d->datasize);
