1	/**
2	 * @file
3	 *
4	 * @copyright
5	 * Copyright 2026 ISCAS.
6	 * SPDX-License-Identifier: Apache-2.0
7	 *
8	 * @test @b openssl_sm3sm4
9	 * @parblock
10	 * Stress test for the Chinese national cryptographic standards SM3
11	 * (GB/T 32905-2016 digest) and SM4 (GB/T 32907-2016 block cipher) via
12	 * OpenSSL's EVP API. SM3 is a Merkle-Damgard hash like SHA-2 but with a
13	 * different integer mixing structure (boolean function rounds + cyclic
14	 * rotates + a message-expansion permutation distinct from SHA-2's
15	 * mod-2^64 sigma sums), so it exercises the ALU/rotate pipes in a phase
16	 * the SHA-2 (additive chains) and SHA-3 (AND-XOR-rotate sponge)
17	 * companion tests do not. SM4 is a 32-round Feistel-like block cipher
18	 * with its own 8-bit S-box, linear L-transform and CK round constants —
19	 * a S-box/round-function structure orthogonal to AES's affine S-box +
20	 * ShiftRows/MixColumns. Two new integer-path phases, one test. Pairing
21	 * the national-crypto (国密) algorithms with a domestic ARM silicon
22	 * validation tool is a natural coverage fit. OpenSSL 3.5 has dedicated
23	 * optimized SM3/SM4 implementations. Each iteration re-encrypts the
24	 * plaintext with SM4-CBC (no padding: 1024 bytes = 64 SM4 blocks, so
25	 * ciphertext length is fixed at 1024) and byte-compares against the
26	 * golden ciphertext, decrypts the golden ciphertext and verifies the
27	 * roundtrip against the plaintext, and recomputes the SM3 digest of the
28	 * plaintext and byte-compares it too (compute->verify on both the cipher
29	 * and digest datapaths).
30	 * @endparblock
31	 */
32	
33	#include "sandstone.h"
34	
35	#if SANDSTONE_SSL_BUILD
36	
37	#include "sandstone_ssl.h"
38	
39	#include <string.h>
40	#include <stdlib.h>
41	
42	#define SM_DATA_SIZE   (1024u)   /* 64 SM4 blocks, no padding needed */
43	#define SM3_DIGEST_SIZE (32)
44	#define SM4_KEY_SIZE  (16)
45	#define SM4_IV_SIZE   (16)
46	#define SM4_BLOCK     (16)
47	
48	struct sm_test_data {
49	    uint8_t sm4_key[SM4_KEY_SIZE], sm4_iv[SM4_IV_SIZE];
50	    uint8_t plaintext[SM_DATA_SIZE];
51	    uint8_t golden_ciphertext[SM_DATA_SIZE];   /* SM4-CBC no padding: 1024 in = 1024 out */
52	    uint8_t golden_sm3[SM3_DIGEST_SIZE];       /* SM3 digest of plaintext */
53	};
54	
55	static void sm4_cbc_encrypt(const uint8_t *key, const uint8_t *iv, const uint8_t *in,
56	                            uint8_t *out, size_t len, int *total_outlen)
57	{
58	    EVP_CIPHER_CTX *ctx = s_EVP_CIPHER_CTX_new();
59	    s_EVP_EncryptInit_ex(ctx, s_EVP_sm4_cbc(), NULL, key, iv);
60	    s_EVP_CIPHER_CTX_set_padding(ctx, 0);
61	    int outlen = 0;
62	    int outlen2 = 0;
63	    s_EVP_EncryptUpdate(ctx, out, &outlen, in, len);
64	    s_EVP_EncryptFinal_ex(ctx, out + outlen, &outlen2);
65	    s_EVP_CIPHER_CTX_free(ctx);
66	    *total_outlen = outlen + outlen2;
67	}
68	
69	static void sm4_cbc_decrypt(const uint8_t *key, const uint8_t *iv, const uint8_t *in,
70	                            uint8_t *out, size_t len, int *total_outlen)
71	{
72	    EVP_CIPHER_CTX *ctx = s_EVP_CIPHER_CTX_new();
73	    s_EVP_DecryptInit_ex(ctx, s_EVP_sm4_cbc(), NULL, key, iv);
74	    s_EVP_CIPHER_CTX_set_padding(ctx, 0);
75	    int outlen = 0;
76	    int outlen2 = 0;
77	    s_EVP_DecryptUpdate(ctx, out, &outlen, in, len);
78	    s_EVP_DecryptFinal_ex(ctx, out + outlen, &outlen2);
79	    s_EVP_CIPHER_CTX_free(ctx);
80	    *total_outlen = outlen + outlen2;
81	}
