83	static void sm3_digest(const uint8_t *msg, size_t len, uint8_t out[SM3_DIGEST_SIZE])
84	{
85	    EVP_MD_CTX *mdctx = s_EVP_MD_CTX_new();
86	    unsigned int md_len = 0;
87	    s_EVP_DigestInit_ex(mdctx, s_EVP_sm3(), NULL);
88	    s_EVP_DigestUpdate(mdctx, msg, len);
89	    s_EVP_DigestFinal_ex(mdctx, out, &md_len);
90	    s_EVP_MD_CTX_free(mdctx);
91	}
92	
