94	{
95	    if (s_EVP_sm3 && s_EVP_sm4_cbc && s_EVP_CIPHER_CTX_new && s_EVP_CIPHER_CTX_free
96	            && s_EVP_EncryptInit_ex && s_EVP_EncryptUpdate && s_EVP_EncryptFinal_ex
97	            && s_EVP_DecryptInit_ex && s_EVP_DecryptUpdate && s_EVP_DecryptFinal_ex
98	            && s_EVP_CIPHER_CTX_set_padding && s_EVP_MD_CTX_new && s_EVP_MD_CTX_free
99	            && s_EVP_DigestInit_ex && s_EVP_DigestUpdate && s_EVP_DigestFinal_ex) {
100	        struct sm_test_data *d = (struct sm_test_data *)malloc(sizeof(*d));
101	        if (!d)
102	            return EXIT_SKIP;
103	
104	        memset_random(d->sm4_key, SM4_KEY_SIZE);
105	        memset_random(d->sm4_iv, SM4_IV_SIZE);
106	        memset_random(d->plaintext, SM_DATA_SIZE);
107	
108	        /* Golden SM4-CBC ciphertext, padding disabled: 1024 bytes is an
109	         * exact multiple of the 16-byte SM4 block, so the output must be
110	         * exactly 1024 bytes. Any other length means padding kicked in —
111	         * a surprise that would silently shift the golden comparison. */
112	        int enc_len = 0;
113	        sm4_cbc_encrypt(d->sm4_key, d->sm4_iv, d->plaintext, d->golden_ciphertext,
114	                        SM_DATA_SIZE, &enc_len);
115	        if (enc_len != (int)SM_DATA_SIZE) {
116	            log_error("SM4-CBC encryption produced %d bytes, expected %u (padding surprise)",
117	                      enc_len, SM_DATA_SIZE);
118	            free(d);
119	            return EXIT_FAILURE;
120	        }
121	
122	        /* Golden SM3 digest of the plaintext */
123	        sm3_digest(d->plaintext, SM_DATA_SIZE, d->golden_sm3);
124	
