2	 * @file
3	 *
4	 * @copyright
5	 * Copyright 2022 Intel Corporation.
6	 * SPDX-License-Identifier: Apache-2.0
7	 *
8	 * @test @b zlib
9	 * @parblock
10	 * This test performs GZIP compression and decompression on random data.
11	 * Because random data is not very compressible, it emphasizes different
12	 * codepaths compared to the other Zlib tests. For this test, level 6
13	 * compression is used.
14	 *
15	 * @note This test requires at least 2 threads to run.
16	 * @endparblock
17	 */
18	
19	#include <assert.h>
20	#include <stdio.h>
21	#include <stdlib.h>
22	#include <string.h>
23	#include <unistd.h>
24	#include <stdint.h>
25	
26	#include <sandstone.h>
27	
28	#include <zlib.h>
29	
30	#define BUF_MAX (size_t)(1024 * 1024 * 4)
31	
32	struct zlib_parameters
33	{
34	    int level;
35	    unsigned maxbuffersize;
36	};
37	
38	static void __attribute__((cold, noreturn)) print_zlib_error(const char *func, int status)
39	{
40	    const char *err_str = zError(status);
41	    if (status == Z_MEM_ERROR)
42	        log_platform_message(SANDSTONE_LOG_ERROR "%s reported memory allocation problems", func);
43	    if (err_str == NULL)
44	        err_str = "unknown error message";
45	
46	    report_fail_msg("%s failed: %s (%d)", func, err_str, status);
47	}
48	
49	static void zlib_gen_buffer(size_t *bufsz, uint8_t ** buf, unsigned maxbuffersize)
50	{
51	    *bufsz = (random32() % maxbuffersize) + 4096;
52	
53	    *buf = malloc(*bufsz + 16);
54	    memset_random(*buf, *bufsz);
55	}
56	
57	static void zcheck(size_t bufsz, uint8_t * buf, int level)
58	{
59	    int status;
60	    uint8_t *out, *back;
61	    size_t csize;
62	    z_stream strm;
63	
64	    out = malloc(bufsz * 2);
65	    back = malloc(bufsz);
66	    memset(&strm, 0, sizeof(strm));
67	
68	    status = deflateInit2(&strm, level, Z_DEFLATED, 15 + 16, 8, Z_DEFAULT_STRATEGY);
69	    if (status != Z_OK)
70	        print_zlib_error("deflateInit2", status);
71	
72	    strm.next_in = buf;
73	    strm.avail_in = bufsz;
74	    strm.next_out = out;
75	    strm.avail_out = bufsz * 2;
76	
77	    do {
78	        status = deflate(&strm, Z_FINISH);
79	        if (status == Z_STREAM_ERROR || status == Z_BUF_ERROR) {
80	            print_zlib_error("deflate", status);
81	        }
82	    } while (status != Z_STREAM_END);
83	
84	    deflateEnd(&strm);
85	
86	    csize = (bufsz * 2) - strm.avail_out;
87	
88	    memset(&strm, 0, sizeof(strm));
89	
90	    strm.zalloc = Z_NULL;
91	    strm.zfree = Z_NULL;
92	    strm.opaque = Z_NULL;
93	
94	    strm.avail_in = csize;
95	    strm.next_in = out;
96	    strm.next_out = back;
97	    strm.avail_out = bufsz;
98	
99	    status = inflateInit2(&strm, 15 + 16);
100	    if (status != Z_OK) {
101	        print_zlib_error("inflateInit2", status);
102	    }
103	
104	    do {
105	        status = inflate(&strm, Z_FINISH);
106	        if (status == Z_NEED_DICT || status == Z_DATA_ERROR ||
107	            status == Z_MEM_ERROR || status == Z_STREAM_ERROR) {
108	            print_zlib_error("inflate", status);
109	        }
110	    } while (status != Z_STREAM_END);
111	
112	    inflateEnd(&strm);
113	
114	    memcmp_or_fail(back, buf, bufsz, "decompressed data");
115	
116	    free(back);
117	    free(out);
118	}
119	
120	static int zlib_init_common(struct test *test, int level)
121	{
122	    // negative value from caller implies they want to add an option
123	    if (level < 0)
124	        level = get_testspecific_knob_value_int(test, "level", -level);
125	
126	    struct zlib_parameters p = {
127	        .level = level,
128	        .maxbuffersize = get_testspecific_knob_value_uint(test, "maxbuffersize", BUF_MAX)
129	    };
130	    static_assert(sizeof(p) == sizeof(test->data),
131	        "Internal assumption broken: change me to allocate memory instead");
132	    memcpy(&test->data, &p, sizeof(p));
133	    return EXIT_SUCCESS;
134	}
135	
136	static int zlib_run_common(struct test *test, int cpu)
137	{
138	    struct zlib_parameters p;
139	    memcpy(&p, &test->data, sizeof(p));
140	
141	    TEST_LOOP(test, 1) {
142	        uint8_t *buf;
143	        size_t bufsz;
144	
145	        zlib_gen_buffer(&bufsz, &buf, p.maxbuffersize);
146	        zcheck(bufsz, buf, p.level);
147	        free(buf);
148	    }
149	
150	    return EXIT_SUCCESS;
151	}
152	
153	static int zlib1_init(struct test *test)
154	{
155	    return zlib_init_common(test, 1);
156	}
157	
158	static int zlib_init(struct test *test)
159	{
160	    return zlib_init_common(test, -6);  // negative to allow override
161	}
162	
163	static int zlib9_init(struct test *test)
164	{
165	    return zlib_init_common(test, 6);
166	}
167	
168	static int zlib_aaa_init(struct test *test)
169	{
170	    return zlib_init_common(test, -9);  // negative to allow override
171	}
172	
173	static int zlib_aaa_run(struct test *test, int cpu)
174	{
175	    struct zlib_parameters p;
176	    memcpy(&p, &test->data, sizeof(p));
177	
178	    TEST_LOOP(test, 1) {
179	        uint8_t *buf;
180	
181	        buf = malloc(p.maxbuffersize);
182	        memset(buf, 'a', p.maxbuffersize);
183	
184	        zcheck(BUF_MAX, buf, p.level);
185	
186	        free(buf);
187	    }
188	
189	    return EXIT_SUCCESS;
190	}
191	
