1	/**
2	 * @file
3	 *
4	 * @copyright
5	 * Copyright 2026 ISCAS.
6	 * SPDX-License-Identifier: Apache-2.0
7	 *
8	 * @test @b isal_igzip
9	 * @parblock
10	 * Compression round-trip via isa-l igzip (stateless deflate -> inflate ->
11	 * byte-compare). Match search (data-dependent branches) + high-density
12	 * stores + Huffman entropy coding: a third compression scheduling sample
13	 * beside zstd/zlib (ITHICA: Zlib was the highest-yield fleet SDC detector;
14	 * CORE179 probe H/X: scheduling diversity is detection rate). Verifies both
15	 * directions: decompressed data must match the original input exactly, and
16	 * a fixed-input re-compression must reproduce the identical deflate stream
17	 * (determinism check on the compressor's data path).
18	 *
19	 * Compression level knob: -O isal_igzip.level=N, valid 0..3, default 1.
20	 * The four levels are four different match-finder data structures inside
21	 * isa-l — 0: static Huffman, no match search; 1: basic hash chain; 2:
22	 * deeper hash history (IGZIP_LVL2_HASH_SIZE); 3: hash map + long match —
23	 * i.e. four data-dependent-branch + integer-multiplier phases over the
24	 * same input. Levels 2/3 additionally exercise the level_buf code path:
25	 * the stateless API REQUIRES a match-finder scratch buffer there (level 1
26	 * may omit it per the header docs, level 0 never searches for matches).
27	 * The buffer is sized ISAL_DEF_LVL{2,3}_MIN — NOT the smaller *_REQ
28	 * constants: this libisal (2.30.0) rejects the bare REQ sizes with
29	 * ISAL_INVALID_LEVEL in stateless mode (stateless needs REQ plus one
30	 * token-history block, which is exactly the header's *_MIN suggested
31	 * size); see level_buf_size() below. The default (no knob) is level 1
32	 * without a level_buf — byte-identical to the historical behavior.
33	 * @endparblock
34	 */
35	
36	#include <sandstone.h>
37	
38	#include <isa-l/igzip_lib.h>
39	
40	#include <string.h>
41	#include <stdlib.h>
42	
43	#define IN_SIZE   (256 * 1024)
44	#define OUT_SIZE  (IN_SIZE + IN_SIZE / 2)
45	
46	namespace {
47	struct igzip_test_data {
48	    uint8_t *input;                 /* read-only after init */
49	    uint8_t *comp_golden;           /* golden deflate stream, once in init */
50	    uint32_t golden_comp_size;
51	    int level;                      /* compression level 0..3 (knob, default 1) */
52	    uint8_t *level_buf;             /* golden-side match-finder scratch (levels 2/3) */
53	};
54	}
55	
56	#define CAST(_x) static_cast<struct igzip_test_data *>(_x)
57	
58	/* Match-finder scratch (level_buf) size the stateless API needs at each
59	 * level: 0 for levels 0/1, ISAL_DEF_LVL{2,3}_MIN for levels 2/3. Empirically
60	 * NOT the smaller ISAL_DEF_LVL{2,3}_REQ: this libisal (2.30.0) rejects the
61	 * bare REQ sizes in stateless mode with ISAL_INVALID_LEVEL — stateless
62	 * needs REQ plus one token-history block, and REQ + TOKEN_SIZE * 1 * IGZIP_K
63	 * is exactly the header's *_MIN suggested size (verified on the host
64	 * library; sizes MIN..DEFAULT all work, MIN is the smallest). */
65	static uint32_t level_buf_size(int level)
66	{
67	    switch (level) {
68	    case 3:  return ISAL_DEF_LVL3_MIN;
69	    case 2:  return ISAL_DEF_LVL2_MIN;
70	    default: return 0;
71	    }
72	}
73	
74	/* Scratch buffers are per-thread: the framework runs one worker thread per
75	 * core and they all share test->data, so anything written during test_run
76	 * must be thread-local (comp is the re-compression destination, decomp the
77	 * inflate destination, and level_buf — levels 2/3 only — the match-finder
78	 * scratch the stateless API requires; all are written every iteration).
79	 * They are allocated lazily on first use and intentionally not freed in
80	 * cleanup, exactly like the openblas_* scratch buffers: the worker threads
81	 * are gone (or never existed) when the main thread runs test_cleanup, and
82	 * the whole forked child exits right after, so the OS reclaims the storage.
83	 * level_buf reuse across iterations is safe: its contents are per-call
84	 * scratch, isa-l reinitializes what it needs on every stateless call
85	 * (has_level_buf_init; verified empirically — pre-dirtied buffers yield
86	 * byte-identical output). */
87	static thread_local uint8_t *comp = nullptr;
88	static thread_local uint8_t *decomp = nullptr;
89	static thread_local uint8_t *level_buf = nullptr;
90	
91	static int isal_igzip_init(struct test *test)
92	{
93	    auto d = new(igzip_test_data);
94	    test->data = d;
95	    /* compression-level knob (mdim/nelems precedent): read once, fail
96	     * loudly on bad values — a silent clamp would run a different
97	     * match-finder phase than the operator asked for */
98	    int64_t lvl = get_testspecific_knob_value_int(test, "level", 1);
99	    if (lvl < 0 || lvl > ISAL_DEF_MAX_LEVEL) {
100	        report_fail_msg("level knob out of range: %ld (valid 0..%d, default 1; 0=static-Huffman no match search, 1=hash chain, 2=deep hash history, 3=hash map + long match)", (long)lvl, ISAL_DEF_MAX_LEVEL);
101	    }
102	    d->level = (int)lvl;
103	    d->input       = (uint8_t *)malloc(IN_SIZE);
104	    d->comp_golden = (uint8_t *)malloc(OUT_SIZE);
105	    uint32_t lb_size = level_buf_size(d->level);
106	    d->level_buf  = lb_size ? (uint8_t *)malloc(lb_size) : nullptr;
107	    if (!d->input || !d->comp_golden || (lb_size && !d->level_buf)) {
108	        report_fail_msg("OOM in isal_igzip init");
109	    }
110	    /* High-entropy random input PLUS compressible structure: alternate
111	     * random blocks with short-period pattern blocks so the match finder
112	     * does real work (pure random is incompressible and skips the match
113	     * logic). Framework RNG only — libc rand is trapped by the framework.
114	     * The mix works for every level: 2/3's deeper match finders do MORE
115	     * work on the pattern blocks, which is the point. */
116	    for (size_t i = 0; i < IN_SIZE; ++i) {
117	        if ((i & 0x3FFF) < 0x2000) {
118	            d->input[i] = (uint8_t)(i & 0x0F);      /* short-period pattern */
119	        } else {
120	            d->input[i] = (uint8_t)random32();      /* random */
121	        }
122	    }
123	    /* golden compression, once, at the knob's level. Levels 2/3 REQUIRE a
124	     * level_buf on the stateless API; level 1 may omit it (the library
125	     * then uses the stream's built-in hash array) and level 0 never
126	     * searches for matches. Default (no knob) = level 1 without a
127	     * level_buf — byte-identical to the historical behavior. */
128	    struct isal_zstream stream;
129	    isal_deflate_stateless_init(&stream);
130	    stream.end_of_stream = 1;
131	    stream.flush = NO_FLUSH;
132	    stream.next_in = d->input;
133	    stream.avail_in = IN_SIZE;
134	    stream.next_out = d->comp_golden;
135	    stream.avail_out = OUT_SIZE;
136	    stream.level = d->level;
137	    if (lb_size) {
138	        stream.level_buf = d->level_buf;
139	        stream.level_buf_size = lb_size;
140	    }
141	    if (isal_deflate_stateless(&stream) != COMP_OK) {
142	        report_fail_msg("golden isal_deflate_stateless failed (level %d)", d->level);
143	    }
144	    d->golden_comp_size = stream.total_out;
145	    return EXIT_SUCCESS;
146	}
147	
148	static int isal_igzip_run(struct test *test, int cpu)
149	{
150	    (void)cpu;
151	    auto d = CAST(test->data);
152	    uint32_t lb_size = level_buf_size(d->level);
153	    long iter = 0;
154	    TEST_LOOP(test, 1) {
155	        /* lazily allocate this thread's scratch buffers */
156	        if (__builtin_expect(!comp || !decomp || (lb_size && !level_buf), 0)) {
157	            comp    = (uint8_t *)malloc(OUT_SIZE);
158	            decomp  = (uint8_t *)malloc(IN_SIZE);
159	            if (lb_size && !level_buf)
160	                level_buf = (uint8_t *)malloc(lb_size);
161	            if (!comp || !decomp || (lb_size && !level_buf))
162	                report_fail_msg("OOM allocating thread scratch (%zu bytes)",
163	                                (size_t)OUT_SIZE + IN_SIZE + lb_size);
164	        }
165	        ++iter;
166	
167	        /* compress the same input again: must reproduce the identical
168	         * stream (compressor data-path determinism — the first SDC check) */
169	        struct isal_zstream stream;
170	        isal_deflate_stateless_init(&stream);
171	        stream.end_of_stream = 1;
172	        stream.flush = NO_FLUSH;
173	        stream.next_in = d->input;
174	        stream.avail_in = IN_SIZE;
175	        stream.next_out = comp;
176	        stream.avail_out = OUT_SIZE;
177	        stream.level = d->level;
178	        if (lb_size) {
179	            stream.level_buf = level_buf;
180	            stream.level_buf_size = lb_size;
181	        }
182	        if (isal_deflate_stateless(&stream) != COMP_OK) {
183	            report_fail_msg("isal_deflate_stateless failed (iteration %ld)", iter);
184	        }
185	        if (stream.total_out != d->golden_comp_size) {
186	            report_fail_msg("compressed size %u != golden %u (iteration %ld)",
187	                            stream.total_out, d->golden_comp_size, iter);
188	        }
189	        memcmp_or_fail(comp, d->comp_golden, d->golden_comp_size);
190	
191	        /* decompress round-trip: must reproduce the input exactly (the
192	         * second SDC check — inflate + match reconstruction). The inflate
193	         * side is level-independent: deflate is deflate. */
194	        struct inflate_state inf;
195	        isal_inflate_init(&inf);
196	        inf.next_in = comp;
197	        inf.avail_in = d->golden_comp_size;
198	        inf.next_out = decomp;
199	        inf.avail_out = IN_SIZE;
200	        if (isal_inflate(&inf) != ISAL_DECOMP_OK) {
201	            report_fail_msg("isal_inflate failed (iteration %ld)", iter);
202	        }
203	        if (inf.total_out != IN_SIZE) {
204	            report_fail_msg("decompressed size %u != %d (iteration %ld)",
205	                            inf.total_out, IN_SIZE, iter);
206	        }
207	        memcmp_or_fail(decomp, d->input, IN_SIZE);
208	    }
209	    return EXIT_SUCCESS;
210	}
211	
212	static int isal_igzip_cleanup(struct test *test)
213	{
214	    auto d = CAST(test->data);
215	    free(d->input); free(d->comp_golden); free(d->level_buf);
216	    delete d;
217	    return EXIT_SUCCESS;
218	}
219	
220	DECLARE_TEST(isal_igzip, "isa-l igzip deflate/inflate round-trip SDC stress (level knob -O isal_igzip.level=0..3, default 1: four match-finder data-structure phases — static-Huffman / hash chain / deep hash history / hash map + long match)")
221	  .groups = DECLARE_TEST_GROUPS(&group_compression),
222	  .test_init = isal_igzip_init,
223	  .test_run = isal_igzip_run,
224	  .test_cleanup = isal_igzip_cleanup,
225	  .fracture_loop_count = 4,
226	  .quality_level = TEST_QUALITY_PROD,
227	END_DECLARE_TEST
