static int crc32_run(struct test *test, int cpu) {
    (void)cpu;
    log_skip(TestResourceIssueSkipCategory,
             "to be implemented (placeholder): ARM __crc32b CRC instruction required");
    return EXIT_SKIP;
}
#endif

static int crc32_finish(struct test *test) {
    (void)test;
    return EXIT_SUCCESS;
}

